    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long m = Long.parseLong(st.nextToken());

        int[] a = new int[n];
        int[] b = new int[n];

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) b[i] = Integer.parseInt(st.nextToken());

        int maxBalance = n; // per block of length n, balance never exceeds n
        int statesCount = (n + 1) * n;
        int INF = Integer.MAX_VALUE / 2;

        int[][] transCost = new int[statesCount][statesCount];
        for (int i = 0; i < statesCount; i++) Arrays.fill(transCost[i], INF);

        // map (balance, mod) to id
        int[][] id = new int[maxBalance + 1][n];
        int idx = 0;
        for (int bal = 0; bal <= maxBalance; bal++) {
            for (int mod = 0; mod < n; mod++) {
                id[bal][mod] = idx++;
            }
        }

        // build transitions for one block of length n
        for (int bal = 0; bal <= maxBalance; bal++) {
            for (int mod = 0; mod < n; mod++) {
                int startId = id[bal][mod];
                int curBal = bal;
                int curMod = mod;
                int cost = 0;
                boolean ok = true;
                for (int step = 0; step < n; step++) {
                    int pos = (curMod + step) % n;
                    // choose open or close
                    int openCost = a[pos];
                    int closeCost = b[pos];

                    // we must keep sequence regular: balance never negative, end non-negative
                    // but within block we don't know final balance; we just simulate all possibilities
                    // To handle all possibilities, we need DP over positions and balance.
                    ok = false;
                    break;
                }
                // The above simple simulation is insufficient; we need full DP per starting state.

            }
        }

        // Full DP per block: for each starting (balance, mod), compute minimal cost to each ending (balance', mod')
        for (int bal = 0; bal <= maxBalance; bal++) {
            for (int mod = 0; mod < n; mod++) {
                int startId = id[bal][mod];
                int[][] dp = new int[n + 1][maxBalance + 1];
                for (int i = 0; i <= n; i++) Arrays.fill(dp[i], INF);
                dp[0][bal] = 0;

                for (int step = 0; step < n; step++) {
                    int pos = (mod + step) % n;
                    for (int curBal = 0; curBal <= maxBalance; curBal++) {
                        int curCost = dp[step][curBal];
                        if (curCost == INF) continue;
                        // open
                        if (curBal + 1 <= maxBalance) {
                            int nc = curCost + a[pos];
                            if (nc < dp[step + 1][curBal + 1]) dp[step + 1][curBal + 1] = nc;
                        }
                        // close
                        if (curBal > 0) {
                            int nc = curCost + b[pos];
                            if (nc < dp[step + 1][curBal - 1]) dp[step + 1][curBal - 1] = nc;
                        }
                    }
                }

                int endMod = (mod + n) % n;
                for (int endBal = 0; endBal <= maxBalance; endBal++) {
                    int c = dp[n][endBal];
                    if (c < INF) {
                        int endId = id[endBal][endMod];
                        if (c < transCost[startId][endId]) transCost[startId][endId] = c;
                    }
                }
            }
        }

        // Min-plus matrix exponentiation of transCost for k = m / n blocks
        long blocks = m / n;
        int size = statesCount;
        long[][] dist = new long[size][size];
        long[][] base = new long[size][size];
        long INF_L = Long.MAX_VALUE / 4;

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                base[i][j] = transCost[i][j] >= INF ? INF_L : transCost[i][j];
                dist[i][j] = (i == j) ? 0 : INF_L;
            }
        }

        while (blocks > 0) {
            if ((blocks & 1) == 1) {
                dist = multiply(dist, base, size, INF_L);
            }
            base = multiply(base, base, size, INF_L);
            blocks >>= 1;
        }

        int startId = id[0][0];
        long ans = dist[startId][id[0][0]];
        System.out.println(ans);
    }

    private static long[][] multiply(long[][] A, long[][] B, int n, long INF) {
        long[][] C = new long[n][n];
        for (int i = 0; i < n; i++) Arrays.fill(C[i], INF);
        for (int i = 0; i < n; i++) {
            for (int k = 0; k < n; k++) {
                long aik = A[i][k];
                if (aik == INF) continue;
                long[] Bk = B[k];
                long[] Ci = C[i];
                for (int j = 0; j < n; j++) {
                    long val = Bk[j];
                    if (val == INF) continue;
                    long nv = aik + val;
                    if (nv < Ci[j]) Ci[j] = nv;
                }
            }
        }
        return C;
    }
