        long INF = Long.MAX_VALUE / 4;
        long[][] dp = new long[n + 1][maxBalance + 1];
        for (int i = 0; i <= n; i++) Arrays.fill(dp[i], INF);
        dp[0][0] = 0;

        for (int i = 0; i < n; i++) {
            int idx = i % n;
            for (int bal = 0; bal <= maxBalance; bal++) {
                long cur = dp[i][bal];
                if (cur == INF) continue;
                // open bracket
                int nb = bal + 1;
                if (nb <= maxBalance) {
                    long cost = cur + a[idx];
                    if (cost < dp[i + 1][nb]) dp[i + 1][nb] = cost;
                }
                // close bracket
                if (bal > 0) {
                    int nb2 = bal - 1;
                    long cost2 = cur + b[idx];
                    if (cost2 < dp[i + 1][nb2]) dp[i + 1][nb2] = cost2;
                }
            }
