public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        long m = fs.nextLong();
        int[] a = new int[n];
        int[] b = new int[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextInt();
        for (int i = 0; i < n; i++) b[i] = fs.nextInt();

        int maxLen = n;
        long INF = Long.MAX_VALUE / 4;

        long[][] dp = new long[maxLen + 1][maxLen + 1];
        for (int i = 0; i <= maxLen; i++)
            Arrays.fill(dp[i], INF);
        dp[0][0] = 0;

        for (int len = 0; len < maxLen; len++) {
            for (int bal = 0; bal <= len; bal++) {
                long cur = dp[len][bal];
                if (cur == INF) continue;
                int pos = len;
                int idx = pos % n;
                // open
                dp[len + 1][bal + 1] = Math.min(dp[len + 1][bal + 1], cur + a[idx]);
                // close
                if (bal > 0) {
                    dp[len + 1][bal - 1] = Math.min(dp[len + 1][bal - 1], cur + b[idx]);
                }
            }
        }

        long[] costBlock = new long[maxLen + 1];
        Arrays.fill(costBlock, INF);
        for (int bal = 0; bal <= maxLen; bal++) {
            costBlock[bal] = dp[maxLen][bal];
        }

        long[] dpBlocks = new long[maxLen + 1];
        Arrays.fill(dpBlocks, INF);
        dpBlocks[0] = 0;

        long blocks = m / n;
        for (int i = 0; i < blocks; i++) {
            long[] next = new long[maxLen + 1];
            Arrays.fill(next, INF);
            for (int bal = 0; bal <= maxLen; bal++) {
                long cur = dpBlocks[bal];
                if (cur == INF) continue;
                for (int delta = 0; delta <= maxLen; delta++) {
                    if (costBlock[delta] == INF) continue;
                    int nb = bal + delta;
                    if (nb > maxLen) continue;
                    next[nb] = Math.min(next[nb], cur + costBlock[delta]);
                }
            }
            dpBlocks = next;
        }

        long ans = dpBlocks[0];
        System.out.println(ans);
    }

    // Fast scanner
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
