public class Main {
    static class State {
        int balance;
        long cost;
        State(int b, long c) { balance = b; cost = c; }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long m = Long.parseLong(st.nextToken());
        int[] a = new int[n];
        int[] b = new int[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) a[i] = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) b[i] = Integer.parseInt(st.nextToken());

        int maxBalance = n; // safe upper bound for balance within one block
        long INF = Long.MAX_VALUE / 4;

        // DP for one block of length n
        long[][] dp = new long[n + 1][maxBalance + 1];
        for (int i = 0; i <= n; i++)
            Arrays.fill(dp[i], INF);
        dp[0][0] = 0;

        for (int i = 0; i < n; i++) {
            for (int bal = 0; bal <= maxBalance; bal++) {
                long cur = dp[i][bal];
                if (cur == INF) continue;
                // open
                if (bal + 1 <= maxBalance)
                    dp[i + 1][bal + 1] = Math.min(dp[i + 1][bal + 1], cur + a[i]);
                // close
                if (bal > 0)
                    dp[i + 1][bal - 1] = Math.min(dp[i + 1][bal - 1], cur + b[i]);
            }
        }

        // collect reachable states after one block
        List<State> states = new ArrayList<>();
        for (int bal = 0; bal <= maxBalance; bal++) {
            if (dp[n][bal] < INF) states.add(new State(bal, dp[n][bal]));
        }

        int S = states.size();
        long[][] trans = new long[S][S];
        for (int i = 0; i < S; i++) Arrays.fill(trans[i], INF);

        // build transitions: from state i to j by applying one block starting with balance states[i].balance
        for (int si = 0; si < S; si++) {
            int startBal = states.get(si).balance;
            long[][] dp2 = new long[n + 1][maxBalance + 1];
            for (int i = 0; i <= n; i++)
                Arrays.fill(dp2[i], INF);
            if (startBal <= maxBalance) dp2[0][startBal] = 0;

            for (int i = 0; i < n; i++) {
                for (int bal = 0; bal <= maxBalance; bal++) {
                    long cur = dp2[i][bal];
                    if (cur == INF) continue;
                    if (bal + 1 <= maxBalance)
                        dp2[i + 1][bal + 1] = Math.min(dp2[i + 1][bal + 1], cur + a[i]);
                    if (bal > 0)
                        dp2[i + 1][bal - 1] = Math.min(dp2[i + 1][bal - 1], cur + b[i]);
                }
            }

            for (int sj = 0; sj < S; sj++) {
                int endBal = states.get(sj).balance;
                if (dp2[n][endBal] < INF) {
                    trans[si][sj] = dp2[n][endBal];
                }
            }
        }

        // min-plus matrix exponentiation of trans^(m/n)
        long blocks = m / n;
        long[][] result = new long[S][S];
        for (int i = 0; i < S; i++) {
            Arrays.fill(result[i], INF);
            result[i][i] = 0;
        }

        long[][] base = trans;
        while (blocks > 0) {
            if ((blocks & 1) == 1) {
                result = multiplyMinPlus(result, base, INF);
            }
            base = multiplyMinPlus(base, base, INF);
            blocks >>= 1;
        }

        // initial state: balance 0, cost 0
        int startIndex = -1, endIndex = -1;
        for (int i = 0; i < S; i++) {
            if (states.get(i).balance == 0) startIndex = i;
            if (states.get(i).balance == 0) endIndex = i;
        }

        long ans = result[startIndex][endIndex];
        System.out.println(ans);
    }

    private static long[][] multiplyMinPlus(long[][] A, long[][] B, long INF) {
        int n = A.length;
        int m = B[0].length;
        int k = B.length;
        long[][] C = new long[n][m];
        for (int i = 0; i < n; i++) Arrays.fill(C[i], INF);
        for (int i = 0; i < n; i++) {
            for (int x = 0; x < k; x++) {
                if (A[i][x] == INF) continue;
                long ax = A[i][x];
                long[] Bx = B[x];
                for (int j = 0; j < m; j++) {
                    if (Bx[j] == INF) continue;
                    long val = ax + Bx[j];
                    if (val < C[i][j]) C[i][j] = val;
                }
            }
        }
        return C;
    }
}

