            for (int bal = 0; bal <= maxBalance; bal++) {
                long cur = dp[i][bal];
                if (cur == INF) continue;
                // open
                if (bal + 1 <= maxBalance) {
                    long val = cur + a[idx];
                    if (val < dp[i + 1][bal + 1]) dp[i + 1][bal + 1] = val;
                }
                // close
                if (bal > 0) {
                    long val = cur + b[idx];
                    if (val < dp[i + 1][bal - 1]) dp[i + 1][bal - 1] = val;
                }
            }
        }

        long[] transCost = new long[maxBalance + 1];
        long[] transDelta = new long[maxBalance + 1];
        for (int bal = 0; bal <= maxBalance; bal++) {
            transCost[bal] = dp[n][bal];
            transDelta[bal] = bal;
        }

        long[] bestCost = new long[maxBalance + 1];
        long[] bestDelta = new long[maxBalance + 1];
        for (int bal = 0; bal <= maxBalance; bal++) {
            bestCost[bal] = transCost[bal];
            bestDelta[bal] = transDelta[bal];
        }

        for (int iter = 0; iter < maxBalance; iter++) {
            boolean improved = false;
            for (int bal = 0; bal <= maxBalance; bal++) {
                long newCost = bestCost[bal] + transCost[(int) bestDelta[bal]];
                long newDelta = bestDelta[(int) bestDelta[bal]];
                if (newCost < bestCost[bal]) {
                    bestCost[bal] = newCost;
                    bestDelta[bal] = newDelta;
                    improved = true;
                }
            }
            if (!improved) break;
        }

        long blocks = m / n;
        int rem = (int) (m % n);

        long[] dpRem = new long[rem + 1];
        Arrays.fill(dpRem, INF);
        dpRem[0] = 0;
        int maxBalRem = maxBalance;

        for (int i = 0; i < rem; i++) {
            int idx = i % n;
            long[] next = new long[rem + 1];
            Arrays.fill(next, INF);
            for (int bal = 0; bal <= maxBalRem && bal <= i; bal++) {
                long cur = dpRem[bal];
                if (cur == INF) continue;
                if (bal + 1 <= maxBalRem) {
                    long val = cur + a[idx];
                    if (val < next[bal + 1]) next[bal + 1] = val;
                }
                if (bal > 0) {
                    long val = cur + b[idx];
                    if (val < next[bal - 1]) next[bal - 1] = val;
                }
            }
            dpRem = next;
        }

        long answer = INF;
        for (int bal = 0; bal <= maxBalance; bal++) {
            long costBlocks = 0;
            long deltaBlocks = bal;
            long k = blocks;
            while (k > 0) {
                if ((k & 1) != 0) {
                    costBlocks += bestCost[(int) deltaBlocks];
                    deltaBlocks = bestDelta[(int) deltaBlocks];
                }
                long[] newBestCost = new long[maxBalance + 1];
                long[] newBestDelta = new long[maxBalance + 1];
                for (int i = 0; i <= maxBalance; i++) {
                    newBestCost[i] = bestCost[(int) bestDelta[i]] + bestCost[i];
                    newBestDelta[i] = bestDelta[(int) bestDelta[i]];
                }
                bestCost = newBestCost;
                bestDelta = newBestDelta;
                k >>= 1;
            }
            if (deltaBlocks <= rem && dpRem[(int) deltaBlocks] < INF) {
                long total = costBlocks + dpRem[(int) deltaBlocks];
                if (total < answer) answer = total;
            }
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return -1;
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + c - '0';
                c = read();
            }
            return val * sign;
        }
    }
